<?php
require_once __DIR__ . '/_layout.php';requirePermission('expenses.manage');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;[$ids,$ph]=financeScopedPlaceholders(currentAgencyIds());$expense=dbFetchOne("SELECT e.*,a.name agency_name,u.fullname creator_name FROM expenses e JOIN agencies a ON a.id=e.agency_id LEFT JOIN users u ON u.id=e.created_by WHERE e.id=? AND e.agency_id IN ($ph)",array_merge([$id],$ids));if(!$expense){http_response_code(404);exit(t('validation.finance_not_found'));}
if(requestMethod()==='POST'){requireCsrfPost();try{$action=$_POST['action']??'';if($action==='decide'){financeAssertPermission('expenses.decide');decideExpense(['expense_id'=>$id,'decision'=>$_POST['decision']??'','reason'=>$_POST['reason']??'','owner_exception'=>$_POST['owner_exception']??null,'owner_exception_reason'=>$_POST['owner_exception_reason']??'','idempotency_key'=>$_POST['idempotency_key']??'']);}elseif($action==='compensate'){createCompensatingExpense(['agency_id'=>$expense['agency_id'],'original_expense_id'=>$id,'category'=>$expense['category'],'description'=>$_POST['description']??'','amount'=>$_POST['amount']??'','method'=>$_POST['method']??'','expense_date'=>$_POST['expense_date']??date('Y-m-d'),'idempotency_key'=>$_POST['idempotency_key']??'']);}else throw new InvalidArgumentException(t('validation.invalid_action'));flash('success',t('message.expense_updated'));}catch(AuthorizationException$e){http_response_code(403);exit(t('validation.not_authorized'));}catch(InvalidArgumentException|DomainException$e){flash('danger',$e->getMessage());}catch(Throwable$e){reportDatabaseError($e,'Expense detail operation failed');flash('danger',t('message.expense_failed'));}safeRedirect('expense_detail.php?id='.$id);}
$compensations=dbFetchAll('SELECT * FROM expenses WHERE original_expense_id=:id ORDER BY created_at,id',['id'=>$id]);backofficeHeader(t('page.expense_detail.title'),'expenses.php');pageHeader('page.expense_detail.title','page.expense_detail.description',['breadcrumbs'=>[['label'=>'nav.finance','href'=>'finance.php'],['label'=>'nav.expenses','href'=>'expenses.php'],['label'=>$expense['description']]]]);?>
<div class="grid"><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e($expense['description'])?></h2></div><dl class="detail-list"><dt><?=e(t('field.agency'))?></dt><dd><?=e($expense['agency_name'])?></dd><dt><?=e(t('field.amount'))?></dt><dd><?=money($expense['amount'],$expense['currency'])?></dd><dt><?=e(t('field.method'))?></dt><dd><?=e($expense['method']?t('option.'.$expense['method']):t('common.legacy_unspecified'))?></dd><dt><?=e(t('field.creator'))?></dt><dd><?=e($expense['creator_name'])?></dd><dt><?=e(t('common.status'))?></dt><dd><?=statusBadge($expense['status'])?></dd><dt><?=e(t('field.reason'))?></dt><dd><?=e($expense['decision_reason'])?></dd></dl><?php if($expense['receipt_path']):?><a class="btn secondary" href="financial_document.php?kind=expense_receipt&id=<?=e($id)?>"><?=e(t('action.download_receipt'))?></a><?php endif;?></section>
<?php if($expense['status']==='pending'&&can('expenses.decide')):?><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('action.decide_expense'))?></h2></div><form method="post"><?=csrfField()?><?=financeIdempotencyField('expense.decide')?><input type="hidden" name="action" value="decide"><label><?=e(t('field.decision'))?><select name="decision"><option value="approved"><?=e(t('action.approve'))?></option><option value="rejected"><?=e(t('action.reject'))?></option></select></label><label><?=e(t('field.reason'))?><input name="reason" required maxlength="255"></label><?php if(currentUserRole()===ROLE_OWNER):?><label><input type="checkbox" name="owner_exception" value="1"> <?=e(t('field.owner_exception'))?></label><label><?=e(t('field.owner_exception_reason'))?><input name="owner_exception_reason" maxlength="255"></label><?php endif;?><button class="btn primary"><?=e(t('action.submit_decision'))?></button></form></section><?php endif;?></div>
<?php if($expense['status']==='approved'&&$expense['expense_type']==='expense'):?><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('action.compensate_expense'))?></h2></div><form method="post"><?=csrfField()?><?=financeIdempotencyField('expense.create')?><input type="hidden" name="action" value="compensate"><label><?=e(t('field.amount'))?><input name="amount" required inputmode="decimal"></label><label><?=e(t('field.method'))?><select name="method"><?php foreach(financePaymentMethods()as$m):?><option value="<?=e($m)?>" <?=$m===$expense['method']?'selected':''?>><?=e(t('option.'.$m))?></option><?php endforeach;?></select></label><label><?=e(t('field.description'))?><input name="description" required maxlength="255"></label><input type="hidden" name="expense_date" value="<?=e(date('Y-m-d'))?>"><button class="btn secondary"><?=e(t('action.compensate_expense'))?></button></form></section><?php endif;?>
<?php if($compensations):?><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('section.compensations'))?></h2></div><div class="table-wrap"><table><thead><tr><th><?=e(t('field.description'))?></th><th><?=e(t('field.amount'))?></th><th><?=e(t('common.status'))?></th></tr></thead><tbody><?php foreach($compensations as$c):?><tr><td><a href="expense_detail.php?id=<?=e($c['id'])?>"><?=e($c['description'])?></a></td><td><?=money($c['amount'],$c['currency'])?></td><td><?=statusBadge($c['status'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><?php backofficeFooter();
